using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            // 1. Setup Katana
            var katana = GameObject.Find("Frank_Damage@Damage_Critical_Katana");
            var katanaTrump = katana?.transform.Find("trump");
            if (katanaTrump != null)
            {
                var rHand = katanaTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_R_Clavicle/CC_Base_R_Upperarm/CC_Base_R_Forearm/CC_Base_R_Hand");
                var pelvis = katanaTrump.Find("root/CC_Base_Hip/CC_Base_Pelvis");
                // Create R_Hand_Weapon
                var rHandWeapon = new GameObject("R_Hand_Weapon");
                result.RegisterObjectCreation(rHandWeapon);
                rHandWeapon.transform.SetParent(rHand, false);
                rHandWeapon.transform.localPosition = new Vector3(0.11f, -0.05f, -0.01f);
                rHandWeapon.transform.localEulerAngles = new Vector3(5.68f, 36.54f, 83.46f);
                var weaponSword = new GameObject("Weapon_Sword");
                result.RegisterObjectCreation(weaponSword);
                weaponSword.transform.SetParent(rHandWeapon.transform, false);
                weaponSword.transform.localPosition = Vector3.zero;
                weaponSword.transform.localEulerAngles = new Vector3(90f, 90f, 0f);
                var weaponBlade = new GameObject("Weapon_Blade");
                result.RegisterObjectCreation(weaponBlade);
                weaponBlade.transform.SetParent(weaponSword.transform, false);
                weaponBlade.transform.localPosition = new Vector3(-0.08f, 0f, 0f);
                weaponBlade.transform.localEulerAngles = Vector3.zero;
                // Create Sword_Case under Pelvis (or CC_Base_Hip)
                var hip = katanaTrump.Find("root/CC_Base_Hip");
                var swordCase = new GameObject("Sword_Case");
                result.RegisterObjectCreation(swordCase);
                swordCase.transform.SetParent(hip, false);
                swordCase.transform.localPosition = new Vector3(-0.15f, 0.05f, -0.1f);
                swordCase.transform.localEulerAngles = new Vector3(25f, 15f, 75f);
                var weaponSwordDummy = new GameObject("Weapon_Sword_Dummy");
                result.RegisterObjectCreation(weaponSwordDummy);
                weaponSwordDummy.transform.SetParent(swordCase.transform, false);
                weaponSwordDummy.transform.localPosition = new Vector3(0.08f, 0f, 0f);
                weaponSwordDummy.transform.localEulerAngles = Vector3.zero;
                // Wire SMRs
                var swordMesh = katana.transform.Find("Sword_Mesh")?.GetComponent<SkinnedMeshRenderer>();
                if (swordMesh != null)
                {
                    result.RegisterObjectModification(swordMesh);
                    swordMesh.rootBone = weaponSword.transform;
                    swordMesh.bones = new Transform[]{weaponSword.transform, weaponBlade.transform};
                }

                var swordDummy = katana.transform.Find("Sword_Dummy")?.GetComponent<SkinnedMeshRenderer>();
                if (swordDummy != null)
                {
                    result.RegisterObjectModification(swordDummy);
                    swordDummy.rootBone = weaponSwordDummy.transform;
                    swordDummy.bones = new Transform[]{weaponSwordDummy.transform};
                }

                var swordCaseMesh = katana.transform.Find("Sword_Case_Mesh")?.GetComponent<SkinnedMeshRenderer>();
                if (swordCaseMesh != null)
                {
                    result.RegisterObjectModification(swordCaseMesh);
                    swordCaseMesh.rootBone = swordCase.transform;
                    swordCaseMesh.bones = new Transform[]{swordCase.transform};
                }

                result.Log("Wired Katana weapons successfully!");
            }

            // 2. Setup GreatSword
            var gs = GameObject.Find("Frank_Damage@Damage_Critical_GreatSword");
            var gsTrump = gs?.transform.Find("trump");
            if (gsTrump != null)
            {
                var rHand = gsTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_R_Clavicle/CC_Base_R_Upperarm/CC_Base_R_Forearm/CC_Base_R_Hand");
                var rHandWeapon = new GameObject("R_Hand_Weapon");
                result.RegisterObjectCreation(rHandWeapon);
                rHandWeapon.transform.SetParent(rHand, false);
                rHandWeapon.transform.localPosition = new Vector3(0.11f, -0.05f, -0.01f);
                rHandWeapon.transform.localEulerAngles = new Vector3(5.68f, 36.54f, 83.46f);
                var gsRoot = new GameObject("GreatSword_Root");
                result.RegisterObjectCreation(gsRoot);
                gsRoot.transform.SetParent(rHandWeapon.transform, false);
                gsRoot.transform.localPosition = Vector3.zero;
                gsRoot.transform.localEulerAngles = Vector3.zero;
                var gsSMR = gs.transform.Find("Greatsword_weapon_Equip")?.GetComponent<SkinnedMeshRenderer>();
                if (gsSMR != null)
                {
                    result.RegisterObjectModification(gsSMR);
                    gsSMR.rootBone = gsRoot.transform;
                    gsSMR.bones = new Transform[]{gsRoot.transform};
                }

                result.Log("Wired GreatSword weapon successfully!");
            }

            // 3. Setup Dual
            var dual = GameObject.Find("Frank_Damage@Damage_Critical_Dual");
            var dualTrump = dual?.transform.Find("trump");
            if (dualTrump != null)
            {
                var rHand = dualTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_R_Clavicle/CC_Base_R_Upperarm/CC_Base_R_Forearm/CC_Base_R_Hand");
                var lHand = dualTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_L_Clavicle/CC_Base_L_Upperarm/CC_Base_L_Forearm/CC_Base_L_Hand");
                // Right sword
                var rHandWeapon = new GameObject("R_Hand_Weapon");
                result.RegisterObjectCreation(rHandWeapon);
                rHandWeapon.transform.SetParent(rHand, false);
                rHandWeapon.transform.localPosition = new Vector3(0.09f, -0.06f, 0.0f);
                rHandWeapon.transform.localEulerAngles = new Vector3(5.68f, 36.54f, 83.46f);
                var swordRBone = new GameObject("Sword_R_Bone");
                result.RegisterObjectCreation(swordRBone);
                swordRBone.transform.SetParent(rHandWeapon.transform, false);
                swordRBone.transform.localPosition = Vector3.zero;
                swordRBone.transform.localEulerAngles = new Vector3(28.13f, 0f, 0f);
                // Left sword
                var lHandWeapon = new GameObject("R_Hand_Weapon001");
                result.RegisterObjectCreation(lHandWeapon);
                lHandWeapon.transform.SetParent(lHand, false);
                lHandWeapon.transform.localPosition = new Vector3(-0.09f, 0.05f, 0.02f);
                lHandWeapon.transform.localEulerAngles = new Vector3(351.7f, 213.19f, 277.02f);
                var swordLBone = new GameObject("Sword_L_Bone");
                result.RegisterObjectCreation(swordLBone);
                swordLBone.transform.SetParent(lHandWeapon.transform, false);
                swordLBone.transform.localPosition = Vector3.zero;
                swordLBone.transform.localEulerAngles = new Vector3(11.15f, 0f, 0f);
                var swordR_SMR = dual.transform.Find("Sword_R")?.GetComponent<SkinnedMeshRenderer>();
                if (swordR_SMR != null)
                {
                    result.RegisterObjectModification(swordR_SMR);
                    swordR_SMR.rootBone = swordRBone.transform;
                    swordR_SMR.bones = new Transform[]{swordRBone.transform};
                }

                var swordL_SMR = dual.transform.Find("Sword_L")?.GetComponent<SkinnedMeshRenderer>();
                if (swordL_SMR != null)
                {
                    result.RegisterObjectModification(swordL_SMR);
                    swordL_SMR.rootBone = swordLBone.transform;
                    swordL_SMR.bones = new Transform[]{swordLBone.transform};
                }

                result.Log("Wired Dual swords successfully!");
            }

            // 4. Setup Warrior
            var warrior = GameObject.Find("Frank_Damage@Damage_Critical_Warrior");
            var warriorTrump = warrior?.transform.Find("trump");
            if (warriorTrump != null)
            {
                var rHand = warriorTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_R_Clavicle/CC_Base_R_Upperarm/CC_Base_R_Forearm/CC_Base_R_Hand");
                var lHand = warriorTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_L_Clavicle/CC_Base_L_Upperarm/CC_Base_L_Forearm/CC_Base_L_Hand");
                // Right sword
                var rHandWeapon = new GameObject("R_Hand_Weapon");
                result.RegisterObjectCreation(rHandWeapon);
                rHandWeapon.transform.SetParent(rHand, false);
                rHandWeapon.transform.localPosition = new Vector3(0.09f, -0.06f, 0.0f);
                rHandWeapon.transform.localEulerAngles = new Vector3(5.68f, 36.54f, 83.46f);
                var swordRBone = new GameObject("Sword_R_Bone");
                result.RegisterObjectCreation(swordRBone);
                swordRBone.transform.SetParent(rHandWeapon.transform, false);
                swordRBone.transform.localPosition = Vector3.zero;
                swordRBone.transform.localEulerAngles = Vector3.zero;
                // Left shield
                var lHandShieldBone = new GameObject("Lhand_Shield_Bone");
                result.RegisterObjectCreation(lHandShieldBone);
                lHandShieldBone.transform.SetParent(lHand, false);
                lHandShieldBone.transform.localPosition = new Vector3(0.05f, 0.05f, -0.01f);
                lHandShieldBone.transform.localEulerAngles = new Vector3(348.75f, 265.85f, 102.72f);
                var shieldRoot = new GameObject("Shield_Root");
                result.RegisterObjectCreation(shieldRoot);
                shieldRoot.transform.SetParent(lHandShieldBone.transform, false);
                shieldRoot.transform.localPosition = new Vector3(-0.15f, 0.0f, 0.0f);
                shieldRoot.transform.localEulerAngles = new Vector3(0.5f, 180.0f, 0.0f);
                var swordR_SMR = warrior.transform.Find("Sword_R")?.GetComponent<SkinnedMeshRenderer>();
                if (swordR_SMR != null)
                {
                    result.RegisterObjectModification(swordR_SMR);
                    swordR_SMR.rootBone = swordRBone.transform;
                    swordR_SMR.bones = new Transform[]{swordRBone.transform};
                }

                var shield_SMR = warrior.transform.Find("Shield")?.GetComponent<SkinnedMeshRenderer>();
                if (shield_SMR != null)
                {
                    result.RegisterObjectModification(shield_SMR);
                    shield_SMR.rootBone = shieldRoot.transform;
                    shield_SMR.bones = new Transform[]{shieldRoot.transform};
                }

                result.Log("Wired Warrior sword and shield successfully!");
            }
        }
    }
}
